INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eed9924a-2a93-58e1-bba8-cd4d0cf49118', 'Bolivia Supreme Decree July 19, 1996 approves regulations', 'Supreme Decree No. 24335 July 19, 1996 approves regulations of the hydrocarbons law', 'The following regulations of the Hydrocarbons Law No. 1689 dated April 30, 1996, whose texts in annexes are part of this supreme decree, are approved.', 'The following regulations of the Hydrocarbons Law No. 1689 dated April 30, 1996, whose texts in annexes are part of this supreme decree, are approved.', 'The following regulations of the Hydrocarbons Law No. 1689 dated April 30, 1996, whose texts in annexes are part of this supreme decree, are approved.', 'Bolivia', 'climate', 'in_force', '1996-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_22', ARRAY['sdg13', 'other sustainability policy', 'bolivia', 'sdg7', 'regulations', 'mandatory']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('844b0cd4-1c23-55b7-9c75-893e9ac990fe', 'Bolivia Forest Law, July 12', 'Forest Law, July 12, 1996', 'The purpose of this law is to regulate the sustainable use and protection of forests and forest lands for the benefit of current and future generations, harmonizing the social, economic and ecological interest of the country.', 'The purpose of this law is to regulate the sustainable use and protection of forests and forest lands for the benefit of current and future generations, harmonizing the social, economic and ecological interest of the country.', 'The purpose of this law is to regulate the sustainable use and protection of forests and forest lands for the benefit of current and future generations, harmonizing the social, economic and ecological interest of the country.', 'Bolivia', 'nature', 'in_force', '1996-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_9', ARRAY['other sustainability policy', 'bolivia', 'regulations', 'mandatory', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('dee10a8e-7ae9-532d-902a-dffa79016b83', 'Bolivia General Regulation of Environmental Management, December 8', 'General Regulation of Environmental Management, December 8, 1995', 'This Regulation regulates environmental management within the framework of what is established by Law No. 1333, except for the chapters that require express legislation or regulation.', 'This Regulation regulates environmental management within the framework of what is established by Law No. 1333, except for the chapters that require express legislation or regulation.', 'This Regulation regulates environmental management within the framework of what is established by Law No. 1333, except for the chapters that require express legislation or regulation.', 'Bolivia', 'climate', 'in_force', '1995-01-01'::date, 'Bolivia', 'https://www.carrotsandsticks.org/policies/19_21', ARRAY['sdg13', 'other sustainability policy', 'bolivia', 'regulations', 'mandatory', 'sdg16', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('59a56dc8-83c9-59f4-8834-765fb34a2ed5', 'Bosnia and Herzegovina Standards of Corporate Governance', 'Standards of Corporate Governance, 2011', 'These Standards of Corporate Governance set out more closely the mechanisms for functioning and protection of interests in interrelations among different stakeholders in a joint stock company.', 'These Standards of Corporate Governance set out more closely the mechanisms for functioning and protection of interests in interrelations among different stakeholders in a joint stock company.', 'These Standards of Corporate Governance set out more closely the mechanisms for functioning and protection of interests in interrelations among different stakeholders in a joint stock company.', 'Bosnia and Herzegovina', 'climate', 'in_force', '2011-01-01'::date, 'Bosnia and Herzegovina', 'https://www.carrotsandsticks.org/policies/20_3', ARRAY['bosnia and herzegovina', 'other sustainability policy', 'sdg7', 'voluntary', 'sdg16', 'sdg9', 'voluntary_frameworks']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('91e6ec9d-d0ae-5311-8942-02c3b8dbacb3', 'Bosnia and Herzegovina Code of Corporate Governance for Companies', 'Code of Corporate Governance for Companies Listed on the Sarajevo Stock Exchange - Securities Exchange', 'The aim of this Code is to improve the competitiveness of the companies of the Federation of BiH, and to make the Federation more attractive to foreign country investors.', 'The aim of this Code is to improve the competitiveness of the companies of the Federation of BiH, and to make the Federation more attractive to foreign country investors.', 'The aim of this Code is to improve the competitiveness of the companies of the Federation of BiH, and to make the Federation more attractive to foreign country investors.', 'Bosnia and Herzegovina', 'climate', 'in_force', '2009-01-01'::date, 'Bosnia and Herzegovina', 'https://www.carrotsandsticks.org/policies/20_1', ARRAY['bosnia and herzegovina', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1d410e0e-812a-5175-a83d-cf96cd6afeba', 'Bosnia and Herzegovina Law on Accounting and Auditing of', 'The Law on Accounting and Auditing of the Federation of Bosnia and Herzegovina', 'This Law regulates the field of accounting and auditing including attaining titles, qualifications and licensing in the accounting profession, organisation and functioning of the bookkeeping and accounting system, preparation and presentation of financial reports, auditing of financial reports, establishing of the Auditing Chamber of the Federation of Bosnia and Herzegovina and establishing a quality assurance review system for audit firms and public oversight.', 'This Law regulates the field of accounting and auditing including attaining titles, qualifications and licensing in the accounting profession, organisation and functioning of the bookkeeping and accounting system, preparation and presentation of financial reports, auditing of financial reports, establishing of the Auditing Chamber of the Federation of Bosnia and Herzegovina and establishing a quality assurance review system for audit firms and public oversight.', 'This Law regulates the field of accounting and auditing including attaining titles, qualifications and licensing in the accounting profession, organisation and functioning of the bookkeeping and accounting system, preparation and presentation of financial reports, auditing of financial reports, establishing of the Auditing Chamber of the Federation of Bosnia and Herzegovina and establishing a quality assurance review system for audit firms and public oversight.', 'Bosnia and Herzegovina', 'climate', 'in_force', '2009-01-01'::date, 'Bosnia and Herzegovina', 'https://www.carrotsandsticks.org/policies/20_4', ARRAY['bosnia and herzegovina', 'mandatory', 'regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a9d631be-5f7a-55c9-9ffd-30faa4c25658', 'Bosnia and Herzegovina Standards of Corporate Governance', 'Standards of Corporate Governance, 2006', 'The Standards of corporate governance for joint stock companies determine detailed mechanisms for functioning and protection of interests in mutual relationships of various stakeholders in the joint stock company. Recommendations and suggestions in the text of the Standards are given with the words “should” and “may”. The joint stock companies are not legally responsible to apply them, but are in that event liable to publish explanation for failing to do so.', 'The Standards of corporate governance for joint stock companies determine detailed mechanisms for functioning and protection of interests in mutual relationships of various stakeholders in the joint stock company. Recommendations and suggestions in the text of the Standards are given with the words “should” and “may”. The joint stock companies are not legally responsible to apply them, but are in that event liable to publish explanation for failing to do so.', 'The Standards of corporate governance for joint stock companies determine detailed mechanisms for functioning and protection of interests in mutual relationships of various stakeholders in the joint stock company. Recommendations and suggestions in the text of the Standards are given with the words “should” and “may”. The joint stock companies are not legally responsible to apply them, but are in that event liable to publish explanation for failing to do so.', 'Bosnia and Herzegovina', 'governance', 'in_force', '2006-01-01'::date, 'Bosnia and Herzegovina', 'https://www.carrotsandsticks.org/policies/20_2', ARRAY['bosnia and herzegovina', 'voluntary_frameworks', 'other sustainability policy', 'sdg16', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('40c186fa-a14c-5f49-bd33-ba072fddd787', 'Botswana Listed Companies on Reporting ESG Information to Investors', 'Guidance for Listed Companies on Reporting ESG Information to Investors', 'The Botswana Stock Exchange''s 2024 Sustainability Disclosure Guidance replaces the 2019 version and aligns with global standards. It provides voluntary reporting guidance on ESG practices for listed companies, focusing on governance, strategy, risk management, metrics, and performance. The target audience is locally listed companies seeking to enhance their sustainability reporting.', 'The Botswana Stock Exchange''s 2024 Sustainability Disclosure Guidance replaces the 2019 version and aligns with global standards. It provides voluntary reporting guidance on ESG practices for listed companies, focusing on governance, strategy, risk management, metrics, and performance. The target audience is locally listed companies seeking to enhance their sustainability reporting.', 'The Botswana Stock Exchange''s 2024 Sustainability Disclosure Guidance replaces the 2019 version and aligns with global standards. It provides voluntary reporting guidance on ESG practices for listed companies, focusing on governance, strategy, risk management, metrics, and performance. The target audience is locally listed companies seeking to enhance their sustainability reporting.', 'Botswana', 'climate', 'in_force', '2024-01-01'::date, 'Botswana', 'https://www.carrotsandsticks.org/policies/21_2', ARRAY['sdg16', 'guidance_frameworks', 'mandatory', 'botswana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3fb20b2f-c865-51ab-9229-059d19aeaacc', 'Botswana Listed Companies on Reporting ESG Information to Investors', 'Guidance for Listed Companies on Reporting ESG Information to Investors', 'This document is a Guidance for BSE listed companies on reporting ESG information to investors. The Guidance is an assimilation of the SSE initiative’s Model Guidance on Reporting ESG Information to Investors. Therefore, this Guidance is a voluntary tool for listed companies and is not part of the BSE Listing Requirements.', 'This document is a Guidance for BSE listed companies on reporting ESG information to investors. The Guidance is an assimilation of the SSE initiative’s Model Guidance on Reporting ESG Information to Investors. Therefore, this Guidance is a voluntary tool for listed companies and is not part of the BSE Listing Requirements.', 'This document is a Guidance for BSE listed companies on reporting ESG information to investors. The Guidance is an assimilation of the SSE initiative’s Model Guidance on Reporting ESG Information to Investors. Therefore, this Guidance is a voluntary tool for listed companies and is not part of the BSE Listing Requirements.', 'Botswana', 'climate', 'in_force', '2018-01-01'::date, 'Botswana', 'https://www.carrotsandsticks.org/policies/21_1', ARRAY['guidance_frameworks', 'sdg13', 'mandatory', 'sdg16', 'sdg12', 'disclosure', 'botswana']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1a4f9896-874a-5e1c-80a7-bd8d59bc2cfe', 'Brazil Bill , of 2022. Creates the national landmark', 'Bill No. 572, of 2022. Creates the national landmark law on Human Rights and Businesses and establishes guidelines for the promotion of public policies on the subject', 'Projeto de Lei No. 572, de 2022, creates a national framework law on Human Rights and Businesses in Brazil, and establishes guidelines for the promotion of public policies on this topic. The proposed law requires companies to respect and protect human rights, conduct due diligence on human rights risks in their operations, and establish mechanisms to remedy any human rights violations that may occur. It also establishes the National Human Rights and Business Forum, which will be responsible for promoting dialogue and cooperation between businesses, civil society, and the government to advance the protection and promotion of human rights in business activities.', 'Projeto de Lei No. 572, de 2022, creates a national framework law on Human Rights and Businesses in Brazil, and establishes guidelines for the promotion of public policies on this topic. The proposed law requires companies to respect and protect human rights, conduct due diligence on human rights risks in their operations, and establish mechanisms to remedy any human rights violations that may occur. It also establishes the National Human Rights and Business Forum, which will be responsible for promoting dialogue and cooperation between businesses, civil society, and the government to advance the protection and promotion of human rights in business activities.', 'Projeto de Lei No. 572, de 2022, creates a national framework law on Human Rights and Businesses in Brazil, and establishes guidelines for the promotion of public policies on this topic. The proposed law requires companies to respect and protect human rights, conduct due diligence on human rights risks in their operations, and establish mechanisms to remedy any human rights violations that may occur. It also establishes the National Human Rights and Business Forum, which will be responsible for promoting dialogue and cooperation between businesses, civil society, and the government to advance the protection and promotion of human rights in business activities.', 'Brazil', 'climate', 'in_force', '2022-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_65', ARRAY['sdg2', 'regulations', 'sdg7', 'sdg17', 'brazil', 'mandatory', 'sdg16', 'sdg15', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bfe389f3-291d-50c0-9f1f-e2ef730a310c', 'Brazil Law , (National Policy on Climate Change)', 'Law No. 14,119/2021 (National Policy on Climate Change)', 'This document provides a technical proposal for the regulation of Law 14119/2021, which establishes the National Policy on Payment for Environmental Services (PES) in Brazil. The law aims to promote the conservation of ecosystems, water resources, soil, biodiversity, and related traditional knowledge, ensuring sustainable development in both rural and urban areas. The document emphasizes the role of various sectors—including governments, civil society, and the private sector—in supporting PES initiatives. It encourages the involvement of indigenous communities, family farmers, and traditional populations in PES, especially in private conservation reserves (RPPNs).
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('743a428f-dd18-5581-b389-52856f3b898b', 'TCFD Alignment - Brazilian Central Bank (Climate Disclosure Guidelines)', 'TCFD Alignment - Brazilian Central Bank (Climate Disclosure Guidelines)', 'This regulation, published on September 15, 2021, establishes disclosure rules for social, environmental, and climate-related risks for financial institutions regulated by the Central Bank of Brazil. The new framework aims to ensure that financial institutions adequately manage and disclose risks related to these areas, enhancing transparency and reducing information asymmetry in the Brazilian financial system. The disclosure requirements are based on the Task Force on Climate-related Financial Disclosures (TCFD), with a broader scope that also includes social and environmental risks.', 'This regulation, published on September 15, 2021, establishes disclosure rules for social, environmental, and climate-related risks for financial institutions regulated by the Central Bank of Brazil. The new framework aims to ensure that financial institutions adequately manage and disclose risks related to these areas, enhancing transparency and reducing information asymmetry in the Brazilian financial system. The disclosure requirements are based on the Task Force on Climate-related Financial Disclosures (TCFD), with a broader scope that also includes social and environmental risks.', 'This regulation, published on September 15, 2021, establishes disclosure rules for social, environmental, and climate-related risks for financial institutions regulated by the Central Bank of Brazil. The new framework aims to ensure that financial institutions adequately manage and disclose risks related to these areas, enhancing transparency and reducing information asymmetry in the Brazilian financial system. The disclosure requirements are based on the Task Force on Climate-related Financial Disclosures (TCFD), with a broader scope that also includes social and environmental risks.', 'Brazil', 'climate', 'in_force', '2021-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_6', ARRAY['guidance_frameworks', 'sdg13', 'other sustainability policy', 'sdg16', 'brazil', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2f9561d1-90c1-55fe-b8a8-a19ee8ddd825', 'Brazil BCB Resolution , September 15', 'BCB Resolution No. 139, September 15, 2021', 'Resolução BCB n° 139 de 15/9/2021 is a resolution issued by the Central Bank of Brazil that establishes new rules for the provision of credit by financial institutions in the country. The resolution introduces changes to the risk-weighting of assets and sets out requirements for the classification of loans and provisions for losses. It also establishes guidelines for the calculation of regulatory capital and introduces new reporting requirements for financial institutions. The aim of the resolution is to promote financial stability and ensure the soundness of the Brazilian banking system.', 'Resolução BCB n° 139 de 15/9/2021 is a resolution issued by the Central Bank of Brazil that establishes new rules for the provision of credit by financial institutions in the country. The resolution introduces changes to the risk-weighting of assets and sets out requirements for the classification of loans and provisions for losses. It also establishes guidelines for the calculation of regulatory capital and introduces new reporting requirements for financial institutions. The aim of the resolution is to promote financial stability and ensure the soundness of the Brazilian banking system.', 'Resolução BCB n° 139 de 15/9/2021 is a resolution issued by the Central Bank of Brazil that establishes new rules for the provision of credit by financial institutions in the country. The resolution introduces changes to the risk-weighting of assets and sets out requirements for the classification of loans and provisions for losses. It also establishes guidelines for the calculation of regulatory capital and introduces new reporting requirements for financial institutions. The aim of the resolution is to promote financial stability and ensure the soundness of the Brazilian banking system.', 'Brazil', 'climate', 'in_force', '2021-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_64', ARRAY['brazil', 'mandatory', 'guidance_frameworks', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9d076c34-d4fc-5b59-9e0f-1bea7d1f42a5', 'Brazil impact of your investments', 'The impact of your investments', 'The CVM launches this special edition of the Letter to the Investor, presenting the main concepts, in a simplified way, and pointing out where the interested party can obtain information on environmental and social factors about their investments in the capitals.', 'The CVM launches this special edition of the Letter to the Investor, presenting the main concepts, in a simplified way, and pointing out where the interested party can obtain information on environmental and social factors about their investments in the capitals.', 'The CVM launches this special edition of the Letter to the Investor, presenting the main concepts, in a simplified way, and pointing out where the interested party can obtain information on environmental and social factors about their investments in the capitals.', 'Brazil', 'climate', 'in_force', '2020-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_61', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'sdg12', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cf943902-76a1-5a0d-bd39-70bcfd5065be', 'CVM Instruction 598 (Securities and Exchange Commission of Brazil)', 'CVM Instruction 598 (Securities and Exchange Commission of Brazil)', 'CVM Resolution No. 20, issued on February 25, 2021, establishes the regulatory framework for securities analysts in Brazil. It sets out the accreditation process for individual and legal entity analysts, outlines professional conduct standards, and mandates the preparation and distribution of analysis reports. These reports must adhere to clear and objective language, ensuring that factual data, projections, and opinions are easily distinguishable. The resolution also requires transparency in the disclosure of conflicts of interest and mandates that analysts and their respective entities disclose their relationships with the entities they analyze. Additionally, it emphasizes compliance with a code of professional conduct, independent analysis, and internal controls to prevent conflicts of interest. The resolution repeals earlier regulations and establishes new reporting and supervisory mechanisms for both individual and institutional analysts, ensuring a robust, accountable, and ethical securities analysis environment in Brazil.', 'CVM Resolution No. 20, issued on February 25, 2021, establishes the regulatory framework for securities analysts in Brazil. It sets out the accreditation process for individual and legal entity analysts, outlines professional conduct standards, and mandates the preparation and distribution of analysis reports. These reports must adhere to clear and objective language, ensuring that factual data, projections, and opinions are easily distinguishable. The resolution also requires transparency in the disclosure of conflicts of interest and mandates that analysts and their respective entities disclose their relationships with the entities they analyze. Additionally, it emphasizes compliance with a code of professional conduct, independent analysis, and internal controls to prevent conflicts of interest. The resolution repeals earlier regulations and establishes new reporting and supervisory mechanisms for both individual and institutional analysts, ensuring a robust, accountable, and ethical securities analysis environment in Brazil.', 'CVM Resolution No. 20, issued on February 25, 2021, establishes the regulatory framework for securities analysts in Brazil. It sets out the accreditation process for individual and legal entity analysts, outlines professional conduct standards, and mandates the preparation and distribution of analysis reports. These reports must adhere to clear and objective language, ensuring that factual data, projections, and opinions are easily distinguishable. The resolution also requires transparency in the disclosure of conflicts of interest and mandates that analysts and their respective entities disclose their relationships with the entities they analyze. Additionally, it emphasizes compliance with a code of professional conduct, independent analysis, and internal controls to prevent conflicts of interest. The resolution repeals earlier regulations and establishes new reporting and supervisory mechanisms for both individual and institutional analysts, ensuring a robust, accountable, and ethical securities analysis environment in Brazil.', 'Brazil', 'climate', 'in_force', '2018-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_2', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ba295e72-1990-5cd8-9fdf-2584944e5c99', 'Brazil Resolution ,661 of May 25', 'Resolution No. 4,661 of May 25, 2018', 'Provides for the guidelines for the application of resources guaranteeing the plans managed by closed supplementary pension entities.', 'Provides for the guidelines for the application of resources guaranteeing the plans managed by closed supplementary pension entities.', 'Provides for the guidelines for the application of resources guaranteeing the plans managed by closed supplementary pension entities.', 'Brazil', 'governance', 'in_force', '2018-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_60', ARRAY['brazil', 'mandatory', 'guidance_frameworks', 'other sustainability policy']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9ef41113-b1c0-51dd-81e3-a5d96f17a757', 'Brazil Corporate Social Responsibility Action Plan', 'Corporate Social Responsibility Action Plan 2015-2018', 'BNDES’ guidelines and principles for a socially and environmentally responsible performance are expressed in its Corporate Social Responsibility Policy (CSR Policy), approved in 2010 and updated in 2014.', 'BNDES’ guidelines and principles for a socially and environmentally responsible performance are expressed in its Corporate Social Responsibility Policy (CSR Policy), approved in 2010 and updated in 2014.', 'BNDES’ guidelines and principles for a socially and environmentally responsible performance are expressed in its Corporate Social Responsibility Policy (CSR Policy), approved in 2010 and updated in 2014.', 'Brazil', 'climate', 'in_force', '2018-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_63', ARRAY['sdg13', 'regulations', 'sdg17', 'mandatory', 'sdg16', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0cbd4011-42c9-5d54-ac57-70edcba52165', 'Brazil State-owned Enterprise Governance Program', 'State-owned Enterprise Governance Program', 'This initiative aims to restore trust between investors and SOE’s, relying, therefore, on the alignment of different interests. Investors, as interested in the efficient and sustainable allocation of its resources; the civil society, employees and outsourced personal of the SOE, interested in maintaining income and employment, and the entities of the state, finally, interested at the viability of investments in the public interest with capital markets funding.', 'This initiative aims to restore trust between investors and SOE’s, relying, therefore, on the alignment of different interests. Investors, as interested in the efficient and sustainable allocation of its resources; the civil society, employees and outsourced personal of the SOE, interested in maintaining income and employment, and the entities of the state, finally, interested at the viability of investments in the public interest with capital markets funding.', 'This initiative aims to restore trust between investors and SOE’s, relying, therefore, on the alignment of different interests. Investors, as interested in the efficient and sustainable allocation of its resources; the civil society, employees and outsourced personal of the SOE, interested in maintaining income and employment, and the entities of the state, finally, interested at the viability of investments in the public interest with capital markets funding.', 'Brazil', 'social', 'in_force', '2017-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_20', ARRAY['sdg8', 'mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('73247a33-e559-5ecd-9450-07880965d0d0', 'Brazil Novo Mercado Listing Regulation', 'Novo Mercado Listing Regulation', 'This regulation establishes the requirements applicable to the trading of securities issued by publicly traded companies on the special listing segment of the stock market operated by BM&FBOVESPA S.A. – Bolsa de Valores, Mercadorias e Futuros (“BM&FBOVESPA”), known as Novo Mercado, which sets forth enhanced corporate governance standards for the listing of such Companies, as well as rules applicable to their Senior Managers and shareholders, including the Controlling Shareholders.', 'This regulation establishes the requirements applicable to the trading of securities issued by publicly traded companies on the special listing segment of the stock market operated by BM&FBOVESPA S.A. – Bolsa de Valores, Mercadorias e Futuros (“BM&FBOVESPA”), known as Novo Mercado, which sets forth enhanced corporate governance standards for the listing of such Companies, as well as rules applicable to their Senior Managers and shareholders, including the Controlling Shareholders.', 'This regulation establishes the requirements applicable to the trading of securities issued by publicly traded companies on the special listing segment of the stock market operated by BM&FBOVESPA S.A. – Bolsa de Valores, Mercadorias e Futuros (“BM&FBOVESPA”), known as Novo Mercado, which sets forth enhanced corporate governance standards for the listing of such Companies, as well as rules applicable to their Senior Managers and shareholders, including the Controlling Shareholders.', 'Brazil', 'governance', 'in_force', '2017-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_32', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ea5d64ce-52e3-5702-9bc2-1f55de69300f', 'Brazil AMEC Stewardship Code', 'AMEC Stewardship Code', 'AMEC’s Technical Commission has found that there are some disperse stewardship initiatives in regulatory and mainly in self-regulatory documents in the Brazilian market, but no national code that gathers the best steward- ship practices. With that in mind, AMEC decided, in the beginning of 2015, to launch the AMEC Stewardship Code. The association created a specific working group (WG) to analyze how the topic has been addressed in Brazil and on a global basis. This work was carried out from November 2015 to May 2016. The WG evaluated trials and errors, difficulties, the evolution of several global codes, and the views of national and international institutional investors about them. The result of this dialogue is compiled in this AMEC Code.', 'AMEC’s Technical Commission has found that there are some disperse stewardship initiatives in regulatory and mainly in self-regulatory documents in the Brazilian market, but no national code that gathers the best steward- ship practices. With that in mind, AMEC decided, in the beginning of 2015, to launch the AMEC Stewardship Code. The association created a specific working group (WG) to analyze how the topic has been addressed in Brazil and on a global basis. This work was carried out from November 2015 to May 2016. The WG evaluated trials and errors, difficulties, the evolution of several global codes, and the views of national and international institutional investors about them. The result of this dialogue is compiled in this AMEC Code.', 'AMEC’s Technical Commission has found that there are some disperse stewardship initiatives in regulatory and mainly in self-regulatory documents in the Brazilian market, but no national code that gathers the best steward- ship practices. With that in mind, AMEC decided, in the beginning of 2015, to launch the AMEC Stewardship Code. The association created a specific working group (WG) to analyze how the topic has been addressed in Brazil and on a global basis. This work was carried out from November 2015 to May 2016. The WG evaluated trials and errors, difficulties, the evolution of several global codes, and the views of national and international institutional investors about them. The result of this dialogue is compiled in this AMEC Code.', 'Brazil', 'governance', 'in_force', '2016-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_21', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5cb38803-5473-5fcd-8f7b-4a21064f9fd4', 'Brazil Self-Regulation Code of Investment Governance', 'Self-Regulation Code of Investment Governance', 'The Self-Regulation Code of Investment Governance, which aims to contribute to the improvement of investment governance practices, mitigate existing risks and help promote The sustainable development of the country’s private pension fund industry, thus benefiting, above all, pension plan members and beneficiaries, instituidores1 and sponsors.', 'The Self-Regulation Code of Investment Governance, which aims to contribute to the improvement of investment governance practices, mitigate existing risks and help promote The sustainable development of the country’s private pension fund industry, thus benefiting, above all, pension plan members and beneficiaries, instituidores1 and sponsors.', 'The Self-Regulation Code of Investment Governance, which aims to contribute to the improvement of investment governance practices, mitigate existing risks and help promote The sustainable development of the country’s private pension fund industry, thus benefiting, above all, pension plan members and beneficiaries, instituidores1 and sponsors.', 'Brazil', 'governance', 'in_force', '2016-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_26', ARRAY['other sustainability policy', 'sdg9', 'regulations', 'sdg16', 'brazil', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('636ff346-c0f1-54d8-9871-b78a67c9788c', 'Brazilian Corporate Governance Code (IBGC)', 'Brazilian Corporate Governance Code (IBGC)', 'The Brazilian Corporate Governance Code for Listed Companies provides a comprehensive framework to enhance corporate governance practices among Brazilian publicly listed companies. The code was developed by the GT Interagentes subgroup, led by the Brazilian Institute of Corporate Governance (IBGC), with the aim of improving Brazil''s competitiveness in the global capital markets by aligning with internationally recognized standards. It incorporates an "apply or explain" approach, offering companies flexibility in adopting principles while encouraging transparency in reporting deviations. The Code covers key areas such as shareholder rights, board of directors'' composition, executive management, conflict of interest management, risk, audit, and compliance frameworks. It provides detailed guidelines on the structure, responsibilities, and operations of corporate bodies, ensuring that companies maintain effective governance practices. Moreover, it emphasizes the need for accountability, transparency, and fairness in corporate governance, fostering trust with shareholders and other stakeholders.', 'The Brazilian Corporate Governance Code for Listed Companies provides a comprehensive framework to enhance corporate governance practices among Brazilian publicly listed companies. The code was developed by the GT Interagentes subgroup, led by the Brazilian Institute of Corporate Governance (IBGC), with the aim of improving Brazil''s competitiveness in the global capital markets by aligning with internationally recognized standards. It incorporates an "apply or explain" approach, offering companies flexibility in adopting principles while encouraging transparency in reporting deviations. The Code covers key areas such as shareholder rights, board of directors'' composition, executive management, conflict of interest management, risk, audit, and compliance frameworks. It provides detailed guidelines on the structure, responsibilities, and operations of corporate bodies, ensuring that companies maintain effective governance practices. Moreover, it emphasizes the need for accountability, transparency, and fairness in corporate governance, fostering trust with shareholders and other stakeholders.', 'The Brazilian Corporate Governance Code for Listed Companies provides a comprehensive framework to enhance corporate governance practices among Brazilian publicly listed companies. The code was developed by the GT Interagentes subgroup, led by the Brazilian Institute of Corporate Governance (IBGC), with the aim of improving Brazil''s competitiveness in the global capital markets by aligning with internationally recognized standards. It incorporates an "apply or explain" approach, offering companies flexibility in adopting principles while encouraging transparency in reporting deviations. The Code covers key areas such as shareholder rights, board of directors'' composition, executive management, conflict of interest management, risk, audit, and compliance frameworks. It provides detailed guidelines on the structure, responsibilities, and operations of corporate bodies, ensuring that companies maintain effective governance practices. Moreover, it emphasizes the need for accountability, transparency, and fairness in corporate governance, fostering trust with shareholders and other stakeholders.', 'Brazil', 'climate', 'in_force', '2016-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_3', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg16', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('0837091d-4599-5d7a-8810-24602a4575d6', 'Brazil Law ,303 of June 30', 'Law No. 13,303 of June 30, 2016', 'Provides for the legal status of public companies, mixed capital companies and their subsidiaries, within the scope of the Union, the States, the Federal District and the Municipalities.', 'Provides for the legal status of public companies, mixed capital companies and their subsidiaries, within the scope of the Union, the States, the Federal District and the Municipalities.', 'Provides for the legal status of public companies, mixed capital companies and their subsidiaries, within the scope of the Union, the States, the Federal District and the Municipalities.', 'Brazil', 'governance', 'in_force', '2016-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_50', ARRAY['regulations', 'sdg11', 'mandatory', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7bc3cf24-04fc-5fa6-bd97-8cf9389fc431', 'Brazilian Corporate Governance Code', 'Brazilian Corporate Governance Code 2016', 'This Brazilian Corporate Governance Code (Code) was prepared by the Grupo de Trabalho Interagentes (GT Interagentes), coordinated by the Brazilian Corporate Governance Institute (Instituto Brasileiro de Governança Corporativa - IBGC) and comprised of 11 of the most important entities related to the capital market. The purpose of the GT Interagentes is to propose discussions and actions to increase Brazil’s competitiveness improving the regulated environment, promoting incentives to increase long-term financing sources, and attracting resources that can ensure appropriate conditions for economic expansion and development of the country.', 'This Brazilian Corporate Governance Code (Code) was prepared by the Grupo de Trabalho Interagentes (GT Interagentes), coordinated by the Brazilian Corporate Governance Institute (Instituto Brasileiro de Governança Corporativa - IBGC) and comprised of 11 of the most important entities related to the capital market. The purpose of the GT Interagentes is to propose discussions and actions to increase Brazil’s competitiveness improving the regulated environment, promoting incentives to increase long-term financing sources, and attracting resources that can ensure appropriate conditions for economic expansion and development of the country.', 'This Brazilian Corporate Governance Code (Code) was prepared by the Grupo de Trabalho Interagentes (GT Interagentes), coordinated by the Brazilian Corporate Governance Institute (Instituto Brasileiro de Governança Corporativa - IBGC) and comprised of 11 of the most important entities related to the capital market. The purpose of the GT Interagentes is to propose discussions and actions to increase Brazil’s competitiveness improving the regulated environment, promoting incentives to increase long-term financing sources, and attracting resources that can ensure appropriate conditions for economic expansion and development of the country.', 'Brazil', 'climate', 'in_force', '2016-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_57', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
