INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('8ea7e6ce-3624-55e0-b80a-c5e32eeda7ba', 'Brazil Draft Resolution on Socio-environmental Responsibility Policy', 'Draft Resolution on Socio-environmental Responsibility Policy', 'It publishes minutes of normative acts that provide for the socio-environmental responsibility of financial institutions and other institutions authorized to operate by the Central Bank of Brazil.', 'It publishes minutes of normative acts that provide for the socio-environmental responsibility of financial institutions and other institutions authorized to operate by the Central Bank of Brazil.', 'It publishes minutes of normative acts that provide for the socio-environmental responsibility of financial institutions and other institutions authorized to operate by the Central Bank of Brazil.', 'Brazil', 'governance', 'in_force', '2012-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_17', ARRAY['brazil', 'mandatory', 'mandatory_regulations', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('92cafe93-b590-5a67-ad07-095c97a2c2d0', 'Brazil CODIM, Pronouncement', 'CODIM, Pronouncement no. 13, 2012', 'This Pronouncement sets up annual report guidelines, in order to foster best practices in reporting, information disclosure, and corporate governance. It stipulates that the annual report should include information on financial, social, environmental and governance aspects of the business, including an overview of its past performance, main risks and opportunities, and the corporate strategy in place to address these items in the short, medium and long-term. Regarding sustainability, it also recommends including a GRI Content Index, and information on adherence to initiatives such as the UN Global Compact, and inclusion in sustainability indexes.', 'This Pronouncement sets up annual report guidelines, in order to foster best practices in reporting, information disclosure, and corporate governance. It stipulates that the annual report should include information on financial, social, environmental and governance aspects of the business, including an overview of its past performance, main risks and opportunities, and the corporate strategy in place to address these items in the short, medium and long-term. Regarding sustainability, it also recommends including a GRI Content Index, and information on adherence to initiatives such as the UN Global Compact, and inclusion in sustainability indexes.', 'This Pronouncement sets up annual report guidelines, in order to foster best practices in reporting, information disclosure, and corporate governance. It stipulates that the annual report should include information on financial, social, environmental and governance aspects of the business, including an overview of its past performance, main risks and opportunities, and the corporate strategy in place to address these items in the short, medium and long-term. Regarding sustainability, it also recommends including a GRI Content Index, and information on adherence to initiatives such as the UN Global Compact, and inclusion in sustainability indexes.', 'Brazil', 'climate', 'in_force', '2012-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_24', ARRAY['sdg2', 'sdg10', 'regulations', 'sdg7', 'sdg11', 'brazil', 'mandatory', 'sdg16', 'disclosure', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
