INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('182c8cb4-315b-5df5-bbad-3db32bad3dea', 'Brazil INEA/PRES Resolution of 12 of December', 'INEA/PRES Resolution No. 64 of 12 of December 2012', 'This policy establishes mandatory annual and verified GHG reporting for obtaining environmental licenses in the state of Rio de Janeiro. The rule applies to the oil and gas, mining and metals, energy and fossil fuels, and chemical sectors, among others.', 'This policy establishes mandatory annual and verified GHG reporting for obtaining environmental licenses in the state of Rio de Janeiro. The rule applies to the oil and gas, mining and metals, energy and fossil fuels, and chemical sectors, among others.', 'This policy establishes mandatory annual and verified GHG reporting for obtaining environmental licenses in the state of Rio de Janeiro. The rule applies to the oil and gas, mining and metals, energy and fossil fuels, and chemical sectors, among others.', 'Brazil', 'climate', 'in_force', '2012-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_66', ARRAY['sdg13', 'sdg7', 'brazil', 'mandatory', 'mandatory_regulations', 'sdg12', 'disclosure', 'sdg15', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
