INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bc8a1242-0c6a-5bd0-9b73-89c53f24c89b', 'Brazil BM&FBOVESPA Recommends Listed Companies Publish a Sustaianbility Report', 'BM&FBOVESPA Recommends Listed Companies Publish a Sustaianbility Report or Explain Why They Do Not', 'The objective of this recommendation is to encourage listed companies to report information and results related to environmental, social and corporate governance issues, providing greater transparency for investors', 'The objective of this recommendation is to encourage listed companies to report information and results related to environmental, social and corporate governance issues, providing greater transparency for investors', 'The objective of this recommendation is to encourage listed companies to report information and results related to environmental, social and corporate governance issues, providing greater transparency for investors', 'Brazil', 'climate', 'in_force', '2012-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_8', ARRAY['other sustainability policy', 'sdg7', 'brazil', 'mandatory', 'sdg16', 'mandatory_regulations', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
