INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c8fc3fc1-2173-52b0-bc52-e5bd56b78c84', 'Brazil Law ,305 of August 2', 'Law No. 12,305 of August 2, 2010', 'This law establishes the National Solid Waste Policy, providing for its principles, objectives and instruments as well as on the guidelines for the integrated and management of solid waste management, including hazardous, the responsibilities of generators and power public and applicable economic instruments.', 'This law establishes the National Solid Waste Policy, providing for its principles, objectives and instruments as well as on the guidelines for the integrated and management of solid waste management, including hazardous, the responsibilities of generators and power public and applicable economic instruments.', 'This law establishes the National Solid Waste Policy, providing for its principles, objectives and instruments as well as on the guidelines for the integrated and management of solid waste management, including hazardous, the responsibilities of generators and power public and applicable economic instruments.', 'Brazil', 'circularity', 'in_force', '2010-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_4', ARRAY['regulations', 'mandatory', 'sdg12', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('99afeda3-8546-5b24-99fe-7784e037c9c0', 'Brazil CVM Instruction 480', 'CVM Instruction 480', 'CVM Instruction 480 is a regulation issued by the Brazilian Securities and Exchange Commission (CVM) in 2009. The regulation aims to improve the transparency and quality of information provided by Brazilian publicly traded companies to investors, and to promote good corporate governance practices. The regulation requires publicly traded companies to disclose more detailed and comprehensive information about their business activities, financial performance, risk management practices, and corporate governance structure. Companies are also required to provide regular updates on their financial and operational performance and to adopt best practices for shareholder relations. The regulation also introduced new requirements for the independence of board members and audit committees, and increased penalties for non-compliance with reporting requirements.', 'CVM Instruction 480 is a regulation issued by the Brazilian Securities and Exchange Commission (CVM) in 2009. The regulation aims to improve the transparency and quality of information provided by Brazilian publicly traded companies to investors, and to promote good corporate governance practices. The regulation requires publicly traded companies to disclose more detailed and comprehensive information about their business activities, financial performance, risk management practices, and corporate governance structure. Companies are also required to provide regular updates on their financial and operational performance and to adopt best practices for shareholder relations. The regulation also introduced new requirements for the independence of board members and audit committees, and increased penalties for non-compliance with reporting requirements.', 'CVM Instruction 480 is a regulation issued by the Brazilian Securities and Exchange Commission (CVM) in 2009. The regulation aims to improve the transparency and quality of information provided by Brazilian publicly traded companies to investors, and to promote good corporate governance practices. The regulation requires publicly traded companies to disclose more detailed and comprehensive information about their business activities, financial performance, risk management practices, and corporate governance structure. Companies are also required to provide regular updates on their financial and operational performance and to adopt best practices for shareholder relations. The regulation also introduced new requirements for the independence of board members and audit committees, and increased penalties for non-compliance with reporting requirements.', 'Brazil', 'climate', 'in_force', '2009-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_10', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
