INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('9a87e8a4-97c4-5716-b682-e1fada5081b6', 'Brazil Code of Best Practice of Corporate Governance (4th', 'Code of Best Practice of Corporate Governance (4th edition)', 'This is the fourth edition of the Code of Best Practice of Corporate Governance of IBGC – the Brazilian Institute of Corporate Governance. The first edition, released in 1999, focused on the Board of Directors alone, and was revised in 2001 to include recommendations for other agents of corporate governance – such as shareholders, managers, auditors and the Fiscal Council. The document was revised again in 2004, with updated content geared to the country’s market demands at the time. In the past five years, since the previous edition of the Code, there have been a number of changes in the Brazilian organizational environment, which include the capital market revival, a large number of new companies going public, the arrival of widely dispersed and diffuse ownership companies, mergers and acquisitions ofl large businesses, setbacks of veterans and newcomers, and the global financial downturn. These factors brought to light a few corporate weaknesses and their fragile governance systems, pointing to the need to implement robust corporate governance practices. The revised Code goes precisely in this direction.', 'This is the fourth edition of the Code of Best Practice of Corporate Governance of IBGC – the Brazilian Institute of Corporate Governance. The first edition, released in 1999, focused on the Board of Directors alone, and was revised in 2001 to include recommendations for other agents of corporate governance – such as shareholders, managers, auditors and the Fiscal Council. The document was revised again in 2004, with updated content geared to the country’s market demands at the time. In the past five years, since the previous edition of the Code, there have been a number of changes in the Brazilian organizational environment, which include the capital market revival, a large number of new companies going public, the arrival of widely dispersed and diffuse ownership companies, mergers and acquisitions ofl large businesses, setbacks of veterans and newcomers, and the global financial downturn. These factors brought to light a few corporate weaknesses and their fragile governance systems, pointing to the need to implement robust corporate governance practices. The revised Code goes precisely in this direction.', 'This is the fourth edition of the Code of Best Practice of Corporate Governance of IBGC – the Brazilian Institute of Corporate Governance. The first edition, released in 1999, focused on the Board of Directors alone, and was revised in 2001 to include recommendations for other agents of corporate governance – such as shareholders, managers, auditors and the Fiscal Council. The document was revised again in 2004, with updated content geared to the country’s market demands at the time. In the past five years, since the previous edition of the Code, there have been a number of changes in the Brazilian organizational environment, which include the capital market revival, a large number of new companies going public, the arrival of widely dispersed and diffuse ownership companies, mergers and acquisitions ofl large businesses, setbacks of veterans and newcomers, and the global financial downturn. These factors brought to light a few corporate weaknesses and their fragile governance systems, pointing to the need to implement robust corporate governance practices. The revised Code goes precisely in this direction.', 'Brazil', 'governance', 'in_force', '2009-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_29', ARRAY['regulations', 'sdg16', 'disclosure', 'brazil', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('db869b0b-9354-5739-b8a4-6bc48db08b98', 'Brazil Resolution of 06/', 'Resolution No. 20 of 06/18/2009', 'This Resolution establishes the requirements necessary for authorization to carry out the activity of collecting used or contaminated lubricating oil and its regulation.', 'This Resolution establishes the requirements necessary for authorization to carry out the activity of collecting used or contaminated lubricating oil and its regulation.', 'This Resolution establishes the requirements necessary for authorization to carry out the activity of collecting used or contaminated lubricating oil and its regulation.', 'Brazil', 'climate', 'in_force', '2009-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_55', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6434a30a-23e1-562e-acc9-55a75c12d59c', 'Brazil Draft Law N/', 'Draft Law N/2008', '"Projeto de Lei N/2008" refers to a bill proposed in the Brazilian Congress in 2008. The bill aimed to establish a legal framework for public-private partnerships (PPPs) in Brazil, which are agreements between the government and private companies for the financing, construction, operation, and maintenance of public infrastructure projects. The bill proposed to streamline the process for awarding and implementing PPPs, increase the participation of private sector companies in public projects, and improve the transparency and accountability of PPP contracts. The bill also introduced new rules for the management of risks associated with PPP projects and established a legal framework for dispute resolution. Although the bill was not passed in its original form, it served as a basis for subsequent legislation that has since been enacted to promote PPPs in Brazil.', '"Projeto de Lei N/2008" refers to a bill proposed in the Brazilian Congress in 2008. The bill aimed to establish a legal framework for public-private partnerships (PPPs) in Brazil, which are agreements between the government and private companies for the financing, construction, operation, and maintenance of public infrastructure projects. The bill proposed to streamline the process for awarding and implementing PPPs, increase the participation of private sector companies in public projects, and improve the transparency and accountability of PPP contracts. The bill also introduced new rules for the management of risks associated with PPP projects and established a legal framework for dispute resolution. Although the bill was not passed in its original form, it served as a basis for subsequent legislation that has since been enacted to promote PPPs in Brazil.', '"Projeto de Lei N/2008" refers to a bill proposed in the Brazilian Congress in 2008. The bill aimed to establish a legal framework for public-private partnerships (PPPs) in Brazil, which are agreements between the government and private companies for the financing, construction, operation, and maintenance of public infrastructure projects. The bill proposed to streamline the process for awarding and implementing PPPs, increase the participation of private sector companies in public projects, and improve the transparency and accountability of PPP contracts. The bill also introduced new rules for the management of risks associated with PPP projects and established a legal framework for dispute resolution. Although the bill was not passed in its original form, it served as a basis for subsequent legislation that has since been enacted to promote PPPs in Brazil.', 'Brazil', 'governance', 'in_force', '2008-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_11', ARRAY['sdg4', 'other sustainability policy', 'regulations', 'sdg17', 'sdg11', 'brazil', 'mandatory', 'sdg16', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cbaae538-c1b6-526a-9c64-1952ef06923c', 'Brazil B3 Corporate Sustainability Index (ISE)', 'B3 Corporate Sustainability Index (ISE)', 'The Corporate Sustainability Index (ISE) is a Brazilian stock market index designed to track the performance of companies recognized for their commitment to corporate sustainability. It is based on the evaluation of companies'' sustainability performance across various dimensions, including environmental, social, financial, and governance factors. Companies are selected for inclusion in the ISE portfolio based on their sustainability practices and their alignment with corporate sustainability strategies. The selection process involves an evaluation by the ISE Governance Committee, which assesses the companies'' performance through a detailed questionnaire covering multiple sustainability indicators. The methodology ensures that companies included in the index demonstrate a commitment to transparency, long-term value creation, and responsible business practices. The ISE is rebalanced semi-annually, and only those companies that meet the inclusion criteria and demonstrate a sustained commitment to sustainability are retained in the index.', 'The Corporate Sustainability Index (ISE) is a Brazilian stock market index designed to track the performance of companies recognized for their commitment to corporate sustainability. It is based on the evaluation of companies'' sustainability performance across various dimensions, including environmental, social, financial, and governance factors. Companies are selected for inclusion in the ISE portfolio based on their sustainability practices and their alignment with corporate sustainability strategies. The selection process involves an evaluation by the ISE Governance Committee, which assesses the companies'' performance through a detailed questionnaire covering multiple sustainability indicators. The methodology ensures that companies included in the index demonstrate a commitment to transparency, long-term value creation, and responsible business practices. The ISE is rebalanced semi-annually, and only those companies that meet the inclusion criteria and demonstrate a sustained commitment to sustainability are retained in the index.', 'The Corporate Sustainability Index (ISE) is a Brazilian stock market index designed to track the performance of companies recognized for their commitment to corporate sustainability. It is based on the evaluation of companies'' sustainability performance across various dimensions, including environmental, social, financial, and governance factors. Companies are selected for inclusion in the ISE portfolio based on their sustainability practices and their alignment with corporate sustainability strategies. The selection process involves an evaluation by the ISE Governance Committee, which assesses the companies'' performance through a detailed questionnaire covering multiple sustainability indicators. The methodology ensures that companies included in the index demonstrate a commitment to transparency, long-term value creation, and responsible business practices. The ISE is rebalanced semi-annually, and only those companies that meet the inclusion criteria and demonstrate a sustained commitment to sustainability are retained in the index.', 'Brazil', 'climate', 'in_force', '2005-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_5', ARRAY['other sustainability policy', 'sdg10', 'regulations', 'sdg7', 'mandatory', 'sdg16', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('86f263b1-7deb-5171-9305-1dfbfcdc96a6', 'Brazil CFC Resolution', 'CFC Resolution No. 1003/04', 'This standard establishes procedures for disclosing information of a social and environmental nature, with the objective of demonstrating to society the entity''s participation and social responsibility.', 'This standard establishes procedures for disclosing information of a social and environmental nature, with the objective of demonstrating to society the entity''s participation and social responsibility.', 'This standard establishes procedures for disclosing information of a social and environmental nature, with the objective of demonstrating to society the entity''s participation and social responsibility.', 'Brazil', 'climate', 'in_force', '2004-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_12', ARRAY['sdg4', 'brazil', 'sdg11', 'mandatory', 'mandatory_regulations', 'sdg15', 'disclosure', 'sdg9', 'sdg3']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3a71c7d1-8fb2-5afd-8619-8f98c9700519', 'Brazil Code of Best Practice of Corporate Governance (3rd', 'Code of Best Practice of Corporate Governance (3rd Edition)', 'This is the third revised and enlarged edition of the Code of Best Practice of Corporate Governance issued by the Brazilian Institute of Corporate Governance (IBGC). Revising and making recommendations on corporate governance practices are tasks that require constant care and attention. This new edition of the Code of Best Practice of Corporate Governance tries to capture the business, legal, and regulatory changes that occurred and affect the corporate environment, in order to present a code that is both up-to-date and up to the challenges of our time.', 'This is the third revised and enlarged edition of the Code of Best Practice of Corporate Governance issued by the Brazilian Institute of Corporate Governance (IBGC). Revising and making recommendations on corporate governance practices are tasks that require constant care and attention. This new edition of the Code of Best Practice of Corporate Governance tries to capture the business, legal, and regulatory changes that occurred and affect the corporate environment, in order to present a code that is both up-to-date and up to the challenges of our time.', 'This is the third revised and enlarged edition of the Code of Best Practice of Corporate Governance issued by the Brazilian Institute of Corporate Governance (IBGC). Revising and making recommendations on corporate governance practices are tasks that require constant care and attention. This new edition of the Code of Best Practice of Corporate Governance tries to capture the business, legal, and regulatory changes that occurred and affect the corporate environment, in order to present a code that is both up-to-date and up to the challenges of our time.', 'Brazil', 'governance', 'in_force', '2004-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_28', ARRAY['regulations', 'sdg16', 'disclosure', 'brazil', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2c698c85-4e1a-574c-af12-246cdf156880', 'Brazil ANA Resolution , of August 26', 'ANA Resolution No. 317, of August 26, 2003', 'To institute the National Registry of Users of Water Resources – CNARH for the mandatory registration of individuals and legal entities of public or private law that use water resources.', 'To institute the National Registry of Users of Water Resources – CNARH for the mandatory registration of individuals and legal entities of public or private law that use water resources.', 'To institute the National Registry of Users of Water Resources – CNARH for the mandatory registration of individuals and legal entities of public or private law that use water resources.', 'Brazil', 'governance', 'in_force', '2003-01-01'::date, 'Brazil', 'https://www.carrotsandsticks.org/policies/22_35', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg6', 'brazil']::text[]) ON CONFLICT (id) DO NOTHING;
